// ============================================================================
// INTERNAL HELPERS
// ============================================================================

// Convert time values to strings
static void format_time_value(char* buf, uint8_t value, size_t buf_size) {
    snprintf(buf, buf_size, "%d", value);
}

// Draw a tickbox (4 states: unmarked/marked × unselected/selected)
static void draw_tickbox(int16_t x, int16_t y, bool is_marked, bool is_selected) {
    tft.fillRect(x, y, 14, 12, COLOR_BG);
    if (is_selected && is_marked) {
        tft.pushImage(x, y, 14, 12, image_tickbox_selected_marked_pixels, (uint16_t)0x0000);
    } else if (is_selected && !is_marked) {
        // Offset by +2x, +1y to center the 10x10 bitmap within the 14x12 space
        tft.drawBitmap(x + 2, y + 1, image_tickbox_selected_unmarked_bits, 10, 10, 0xDB3E);
    } else if (!is_selected && is_marked) {
        tft.pushImage(x, y, 14, 12, image_tickbox_marked_pixels, (uint16_t)0x0000);
    } else {
        // Offset by +2x, +1y to center the 10x10 image within the 14x12 space
        tft.pushImage(x + 2, y + 1, 10, 10, image_tickbox_unselected_unmarked_pixels, (uint16_t)0x0000);
    }
}

// Draw a time indicator arrow
static void draw_time_indicator(int16_t x, int16_t y, bool is_selected) {
    tft.fillRect(x, y, 5, 10, COLOR_BG);
    if (is_selected) {
        tft.drawBitmap(x, y, image_time_indicator_selected_bits, 5, 10, COLOR_ACCENT);
    } else {
        tft.pushImage(x, y, 5, 10, image_time_indicator_unselected_pixels, (uint16_t)0x0000);
    }
}

// Draw a playlist pill
static void draw_playlist_pill(int16_t x, int16_t y, const char* playlist_name, bool is_selected) {
    tft.fillRect(x, y, 115, 17, COLOR_BG);
    if (is_selected) {
        tft.pushImage(x, y, 115, 17, image_playlist_pill_selected_pixels, (uint16_t)0x0000);
    } else {
        tft.pushImage(x, y, 115, 16, image_playlist_pill_unselected_pixels, (uint16_t)0x0000);
    }
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(1);
    tft.drawString(playlist_name, x + 5, y + 5);
}

