// Global state reference (defined in app_task.cpp)
extern HypeRestState g_hype_rest_state;

void draw_settings_hype_rest_full() {
    const HypeRestState& state = g_hype_rest_state;
    char buf[8];

    // Background
    tft.fillScreen(COLOR_BG);
    draw_topbar();

    // === HYPE SECTION ===
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(2);
    tft.drawString("Hype:", 20, 33);

    // Time label
    tft.setTextSize(1);
    tft.drawString("Time:", 90, 74);

    // Playlist label
    tft.drawString("Playlist:", 90, 110);

    // Exercise based time label
    tft.drawString("Exercise based time", 143, 47);

    // Clock icon
    tft.drawBitmap(63, 70, image_clock_quarters_bits, 15, 16, TFT_WHITE);

    // Music icon
    tft.drawBitmap(63, 105, image_music_bits, 14, 16, TFT_WHITE);

    // Hype checkbox (item 0)
    draw_tickbox(125, 45, state.hype_exercise_based_time, state.selected_item == 0);

    // Hype minutes (item 1)
    draw_time_indicator(125, 73, state.selected_item == 1);
    format_time_value(buf, state.hype_minutes, sizeof(buf));
    tft.setTextColor(TFT_WHITE);
    tft.drawString(buf, 135, 74);
    tft.setTextColor(state.selected_item == 1 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK);
    tft.drawString("Minute(s)", 145, 74);

    // Hype seconds (item 2)
    draw_time_indicator(202, 73, state.selected_item == 2);
    format_time_value(buf, state.hype_seconds, sizeof(buf));
    tft.setTextColor(TFT_WHITE);
    tft.drawString(buf, 213, 74);
    tft.setTextColor(state.selected_item == 2 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK);
    tft.drawString("Second(s)", 231, 74);

    // Hype playlist (item 3)
    draw_time_indicator(280, 107, state.selected_item == 3);
    draw_playlist_pill(160, 104, dummy_playlists[state.hype_playlist_index], state.selected_item == 3);

    // === REST SECTION ===
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(2);
    tft.drawString("Rest:", 20, 135);

    // Time label
    tft.setTextSize(1);
    tft.drawString("Time:", 90, 176);

    // Playlist label
    tft.drawString("Playlist:", 90, 212);

    // Exercise based time label
    tft.drawString("Exercise based time", 143, 149);

    // Clock icon
    tft.drawBitmap(63, 172, image_clock_quarters_bits, 15, 16, TFT_WHITE);

    // Music icon
    tft.drawBitmap(63, 207, image_music_bits, 14, 16, TFT_WHITE);

    // Rest checkbox (item 4)
    draw_tickbox(125, 146, state.rest_exercise_based_time, state.selected_item == 4);

    // Rest minutes (item 5)
    draw_time_indicator(125, 175, state.selected_item == 5);
    format_time_value(buf, state.rest_minutes, sizeof(buf));
    tft.setTextColor(TFT_WHITE);
    tft.drawString(buf, 135, 176);
    tft.setTextColor(state.selected_item == 5 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK);
    tft.drawString("Minute(s)", 145, 176);

    // Rest seconds (item 6)
    draw_time_indicator(203, 175, state.selected_item == 6);
    format_time_value(buf, state.rest_seconds, sizeof(buf));
    tft.setTextColor(TFT_WHITE);
    tft.drawString(buf, 213, 176);
    tft.setTextColor(state.selected_item == 6 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK);
    tft.drawString("Second(s)", 231, 176);

    // Rest playlist (item 7)
    draw_time_indicator(280, 210, state.selected_item == 7);
    draw_playlist_pill(160, 207, dummy_playlists[state.rest_playlist_index], state.selected_item == 7);
}

// Redraw only a single item by index (flicker-free dirty rect update)
void draw_settings_hype_rest_item(uint8_t item_index) {
    const HypeRestState& state = g_hype_rest_state;
    char buf[8];
    tft.setTextSize(1);
    tft.setTextDatum(TL_DATUM);

    switch (item_index) {
        case 0: // Hype checkbox
            draw_tickbox(125, 45, state.hype_exercise_based_time, state.selected_item == 0);
            break;
        case 1: // Hype minutes
            draw_time_indicator(125, 73, state.selected_item == 1);
            tft.fillRect(135, 74, 20, 10, COLOR_BG);
            format_time_value(buf, state.hype_minutes, sizeof(buf));
            tft.setTextColor(TFT_WHITE, COLOR_BG);
            tft.drawString(buf, 135, 74);
            tft.setTextColor(state.selected_item == 1 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK, COLOR_BG);
            tft.drawString("Minute(s)", 145, 74);
            break;
        case 2: // Hype seconds
            draw_time_indicator(202, 73, state.selected_item == 2);
            tft.fillRect(213, 74, 18, 10, COLOR_BG);
            format_time_value(buf, state.hype_seconds, sizeof(buf));
            tft.setTextColor(TFT_WHITE, COLOR_BG);
            tft.drawString(buf, 213, 74);
            tft.setTextColor(state.selected_item == 2 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK, COLOR_BG);
            tft.drawString("Second(s)", 231, 74);
            break;
        case 3: // Hype playlist
            draw_time_indicator(280, 107, state.selected_item == 3);
            draw_playlist_pill(160, 104, dummy_playlists[state.hype_playlist_index], state.selected_item == 3);
            break;
        case 4: // Rest checkbox
            draw_tickbox(125, 146, state.rest_exercise_based_time, state.selected_item == 4);
            break;
        case 5: // Rest minutes
            draw_time_indicator(125, 175, state.selected_item == 5);
            tft.fillRect(135, 176, 20, 10, COLOR_BG);
            format_time_value(buf, state.rest_minutes, sizeof(buf));
            tft.setTextColor(TFT_WHITE, COLOR_BG);
            tft.drawString(buf, 135, 176);
            tft.setTextColor(state.selected_item == 5 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK, COLOR_BG);
            tft.drawString("Minute(s)", 145, 176);
            break;
        case 6: // Rest seconds
            draw_time_indicator(203, 175, state.selected_item == 6);
            tft.fillRect(213, 176, 18, 10, COLOR_BG);
            format_time_value(buf, state.rest_seconds, sizeof(buf));
            tft.setTextColor(TFT_WHITE, COLOR_BG);
            tft.drawString(buf, 213, 176);
            tft.setTextColor(state.selected_item == 6 && state.edit_mode ? COLOR_ACCENT : COLOR_GREY_TRACK, COLOR_BG);
            tft.drawString("Second(s)", 231, 176);
            break;
        case 7: // Rest playlist
            draw_time_indicator(280, 210, state.selected_item == 7);
            draw_playlist_pill(160, 207, dummy_playlists[state.rest_playlist_index], state.selected_item == 7);
            break;
        default:
            break;
    }
}

